import { installSharedAdmin } from "@/lib/install-shared-admin"
import { StrictMode } from "react"
import { createRoot } from "react-dom/client"
import { App } from "@/App"
import { TooltipProvider } from "@/components/ui/tooltip"
import { Toaster } from "@/components/ui/sonner"
import {
  getRegisteredAdminStyles,
  sealAdminExtensionRegistration,
} from "@/lib/admin-extension-registry"
import { getAdminParams } from "@/lib/admin-params"
import { getSharedExtensionHost } from "@/lib/extensions"
import {
  injectTailwindIntoShadow,
  loadCssText,
  mirrorViteDevStylesIntoShadow,
} from "@/lib/inject-shadow-css"
import { preloadRemoteWorkspaceStartup } from "@/lib/workspace-persistence"
import { ShadowRootProvider } from "@/lib/shadow-root"
// Extracted to dist/mapsvg-admin-react.css and injected into the shadow root.
import "@/index.css"

const ROOT_ID = "mapsvg-admin-react-root"

function getCssUrl(): string {
  const fromParams = getAdminParams().cssUrl
  if (fromParams) return fromParams

  const script = document.querySelector<HTMLScriptElement>('script[src*="mapsvg-admin-react.js"]')
  if (script?.src) {
    return script.src.replace(/mapsvg-admin-react\.js(?:\?.*)?$/, "mapsvg-admin-react.css")
  }
  return ""
}

async function mount() {
  installSharedAdmin()
  getSharedExtensionHost()
  const paidStyles = getRegisteredAdminStyles()

  // All paid admin bundles are WordPress dependencies of this script. Seal
  // registration before React renders so late bundle timing can never mutate UI.
  sealAdminExtensionRegistration()

  // Overlap the bounded metadata read with stylesheet loading and React mount.
  preloadRemoteWorkspaceStartup()

  const host = document.getElementById(ROOT_ID)
  if (!host) {
    console.error(`[mapsvg-admin-react] #${ROOT_ID} not found`)
    return
  }

  document.body.classList.add("mapsvg-react-admin", "mapsvg-edit-screen")

  // Preserve the WordPress bootstrap logo while styles load and React has no UI.
  const startup = host.shadowRoot?.querySelector("[data-mapsvg-admin-startup]")
    ?? host.querySelector("[data-mapsvg-admin-startup]")
  const shadow = host.shadowRoot ?? host.attachShadow({ mode: "open" })
  shadow.replaceChildren(...(startup ? [startup] : []))

  if (import.meta.env.DEV) {
    mirrorViteDevStylesIntoShadow(shadow)
  } else {
    const cssUrl = getCssUrl()
    const styleSources = [...(cssUrl ? [{ id: "app", url: cssUrl }] : []), ...paidStyles]

    if (!cssUrl) {
      console.error("[mapsvg-admin-react] cssUrl missing — core styles will not load in shadow root")
    }

    for (const styleSource of styleSources) {
      try {
        const cssText = await loadCssText(styleSource.url)
        injectTailwindIntoShadow(shadow, cssText, styleSource.id)
      } catch (err) {
        console.error(
          `[mapsvg-admin-react] failed to inject CSS "${styleSource.id}" into shadow root`,
          err,
        )
      }
    }
  }

  // Optional paid code editor owns its loader/CDN styles. Lite does not load Monaco.
  getSharedExtensionHost().get<{ initialize?: (shadow: ShadowRoot) => void }>("admin.panel", "code-editor")?.initialize?.(shadow)

  const appRoot = document.createElement("div")
  appRoot.id = "mapsvg-admin-react-app"
  shadow.appendChild(appRoot)

  const portalRoot = document.createElement("div")
  portalRoot.id = "mapsvg-admin-react-portal"
  shadow.appendChild(portalRoot)

  createRoot(appRoot).render(
    <StrictMode>
      <ShadowRootProvider shadowRoot={shadow} portalContainer={portalRoot}>
        <TooltipProvider delayDuration={400}>
          <App />
          <Toaster />
        </TooltipProvider>
      </ShadowRootProvider>
    </StrictMode>,
  )
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => {
    void mount()
  })
} else {
  void mount()
}
